#!/bin/bash

# update-amalgamation.sh replaces the libvsql C in internal/amalgamation with
# the C from a vsql amalgamation (vsql-VERSION-amalgamation.zip from a vsql
# release, or the folder it unzips to). With no arguments, or a version, the zip
# is downloaded from the latest (or that) vsql release:
#
#   scripts/update-amalgamation.sh
#   scripts/update-amalgamation.sh v1.2.3
#   scripts/update-amalgamation.sh vsql-v1.2.3-amalgamation.zip
#
# Only what's needed to compile libvsql is copied: libvsql.c, which has all of
# libvsql's C (with the garbage collector) for every OS and architecture in one
# file, libvsql.h and the licenses. libvsql_flags.gypi is generated from the
# libraries in vsql.mk, which are the ones that V used to build libvsql on each
# OS and architecture, and is included by binding.gyp. libvsql.c defines
# everything else it needs for the OS and architecture itself.
#
# binding.gyp compiles internal/amalgamation/libvsql.c into the addon, with the
# options from the amalgamation's Makefile (-std=gnu11 -fwrapv -w).

set -euo pipefail

source="${1:-latest}"
root="$(cd "$(dirname "$0")/.." && pwd)"
out="$root/internal/amalgamation"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

if [ ! -e "$source" ]; then
  version="$source"
  if [ "$version" = latest ]; then
    version="$(curl -fsSL https://api.github.com/repos/elliotchance/vsql/releases/latest |
      sed -n 's/^ *"tag_name": *"\(.*\)",$/\1/p')"
  fi
  zip="vsql-$version-amalgamation.zip"
  echo "Downloading $zip"
  curl -fsSL -o "$tmp/$zip" \
    "https://github.com/elliotchance/vsql/releases/download/$version/$zip"
  source="$tmp/$zip"
fi

if [ -f "$source" ]; then
  unzip -q "$source" -d "$tmp/unzipped"
  source="$(dirname "$(find "$tmp/unzipped" -name libvsql.h | head -1)")"
fi

if [ ! -f "$source/libvsql.h" ] || [ ! -f "$source/libvsql.c" ]; then
  echo "$1 isn't a vsql amalgamation (there's no libvsql.h or libvsql.c)" >&2
  exit 1
fi

if [ ! -f "$source/vsql.mk" ]; then
  echo "$1 has no vsql.mk (it may be from before vsql v1.7.58)" >&2
  exit 1
fi

rm -rf "$out"
mkdir -p "$out"
for name in libvsql.c libvsql.h LICENSE LICENSE-V; do
  cp "$source/$name" "$out/"
done

# The libraries for each OS and architecture in vsql.mk (in a block that starts
# with "ifeq ($(VSQL_OS)_$(VSQL_ARCH),OS_ARCH)"), as a condition on gyp's OS
# and target_arch (such as OS=="mac" and target_arch=="arm64").
flags="$root/libvsql_flags.gypi"
{
  echo "# Generated by scripts/update-amalgamation.sh. DO NOT EDIT."
  echo "#"
  echo "# The libraries that V used to build libvsql, from the vsql.mk of the"
  echo "# amalgamation."
  echo "{"
  echo "  'target_defaults': {"
  echo "    'conditions': ["
  sed -n 's/^ifeq (\$(VSQL_OS)_\$(VSQL_ARCH),\(.*\))$/\1/p' "$source/vsql.mk" |
  while read -r os_arch; do
    os="${os_arch%_*}"
    arch="${os_arch#*_}"
    case "$os" in
      macos) os=mac ;;
      windows) os=win ;;
    esac
    case "$arch" in
      amd64) arch=x64 ;;
    esac

    libraries=""
    for arg in $(sed -n "/^ifeq (\$(VSQL_OS)_\$(VSQL_ARCH),$os_arch)\$/,/^endif/s/^LIBVSQL_FLAGS *= *//p" "$source/vsql.mk"); do
      case "$arg" in
        # Options for linking libvsql as a shared library.
        -Wl,*) ;;
        -l*) libraries="$libraries${libraries:+, }'$arg'" ;;
        *) echo "Unknown flag for $os_arch in vsql.mk: $arg" >&2; exit 1 ;;
      esac
    done
    echo "      ['OS==\"$os\" and target_arch==\"$arch\"', {"
    echo "        'libraries': [$libraries],"
    echo "      }],"
  done
  echo "    ],"
  echo "  },"
  echo "}"
} > "$flags"

echo "Updated $out and $flags from ${1:-the latest release}"
